<?php
declare(strict_types=1);namespace App\Application\Ledger;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Application\Ledger\Posting\AccountingEventMappingService;use App\Models\FinancialPostingProfile;use Illuminate\Database\UniqueConstraintViolationException;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
/* REQ-ACC-001: an APPROVED posting profile (explicit override) wins; otherwise the event is resolved through the tenant's versioned accounting event mapping (Posting\AccountingEventMappingService). Idempotent per (event, reference). */
final class FinancialPostingService{public function __construct(private LedgerService$ledger,private AuditWriter$audit,private OutboxWriter$outbox,private ?AccountingEventMappingService$mappings=null){}public function post(?string$tenant,string$event,string$referenceId,int$amount,string$currency,string$correlation):string{if($amount<=0)throw ValidationException::withMessages(['amount'=>__('wave4.positive_amount')]);if($existing=$this->existing($event,$referenceId))return$existing;$p=FinancialPostingProfile::where(['event_type'=>$event,'currency'=>$currency,'status'=>'APPROVED'])->where(fn($q)=>$q->where('tenant_id',$tenant)->orWhereNull('tenant_id'))->orderByRaw('tenant_id IS NULL ASC')->first();$source=['event'=>$event,'source'=>'posting_profile'];if($p){$debit=$p->debit_account_id;$credit=$p->credit_account_id;}else{$m=($this->mappings??app(AccountingEventMappingService::class))->resolve($tenant,$event,$currency);if(!$m)throw ValidationException::withMessages(['posting_profile'=>__('wave4.posting_profile_missing')]);$debit=$m['debit_account_id'];$credit=$m['credit_account_id'];$source=['event'=>$event,'source'=>'event_mapping','mapping_id'=>$m['mapping_id'],'mapping_version'=>$m['version']];}/* JournalLine is declared inside Journal.php (no PSR-4 file of its own): load it before LedgerService builds lines. */class_exists(\App\Domain\Ledger\Journal::class);try{$id=$this->ledger->post($tenant,$event,$referenceId,$currency,[['account_id'=>$debit,'debit_minor'=>$amount,'credit_minor'=>0,'dimensions'=>$source],['account_id'=>$credit,'debit_minor'=>0,'credit_minor'=>$amount,'dimensions'=>$source]],$correlation);}catch(UniqueConstraintViolationException$e){if($existing=$this->existing($event,$referenceId))return$existing;throw$e;}$this->audit->record('ledger.event.posted','journal',$id,['event'=>$event,'reference_id'=>$referenceId]+$source);$this->outbox->record('ledger.event.posted','journal',$id,['journal_id'=>$id,'event'=>$event]);return$id;}private function existing(string$event,string$referenceId):?string{return DB::table('journals')->where(['reference_type'=>$event,'reference_id'=>$referenceId,'status'=>'POSTED'])->value('id');}}
